/**
 * Model Test Service
 * Handles testing of model configurations with user API keys
 */

import { BaseService } from './BaseService';
import { AIModels } from '../../agents/inferutils/config.types';
import { infer, InferError } from '../../agents/inferutils/core';
import { createUserMessage } from '../../agents/inferutils/common';
import type { TestResult, ModelTestRequest, ModelTestResult } from '../types';
import { isErrorWithMessage } from '../types';

export class ModelTestService extends BaseService {
    /**
     * Test a model configuration by making a simple chat request using core inference
     */
    async testModelConfig({
        modelConfig,
        userApiKeys,
        testPrompt = "Hello! Please respond with 'Test successful' to confirm the connection is working."
    }: ModelTestRequest): Promise<ModelTestResult> {
        const startTime = Date.now();
        const modelName: string = modelConfig.name;
        const cleanModelName = modelName.replace(/\[.*?\]/, ''); // Remove provider prefix for display

        try {
            const testMessage = createUserMessage(testPrompt);

            // Use core inference system to test the model configuration
            const response = await infer({
                env: this.env,
                metadata: { agentId: `test-${Date.now()}`, userId: 'system' }, // Generate unique test ID
                messages: [testMessage],
                modelName: modelName,
                maxTokens: Math.min(modelConfig.max_tokens || 100, 100), // Limit to 100 tokens for test
                temperature: modelConfig.temperature || 0.1,
                reasoning_effort: modelConfig.reasoning_effort,
                userApiKeys,
                actionKey: 'testModelConfig',
            });

            const endTime = Date.now();
            const latencyMs = endTime - startTime;

            const content = response.string || '';

            return {
                success: true,
                responsePreview: content.length > 100 ? content.substring(0, 100) + '...' : content,
                latencyMs,
                modelUsed: cleanModelName,
            };

        } catch (error: unknown) {
            const endTime = Date.now();
            const latencyMs = endTime - startTime;

            // Handle InferError and other errors from core system
            let rawError = 'Unknown error occurred';

            if (error instanceof InferError) {
                rawError = error.message;
            } else if (error instanceof Error) {
                rawError = error.message;
            } else if (isErrorWithMessage(error)) {
                // Handle error objects from the core system
                if (error.message) {
                    rawError = error.message;
                } else if (error.error?.message) {
                    rawError = error.error.message;
                } else {
                    rawError = JSON.stringify(error);
                }
            } else {
                rawError = String(error);
            }

            return {
                success: false,
                error: rawError,
                latencyMs,
                modelUsed: cleanModelName
            };
        }
    }

    /**
     * Test a specific provider's API key using core inference
     */
    async testProviderKey(provider: string, apiKey: string): Promise<TestResult> {
        const startTime = Date.now();

        try {
            // Get a simple model for this provider to test with
            const testModel = this.getTestModelForProvider(provider);
            if (!testModel) {
                return {
                    success: false,
                    error: `No test model available for provider: ${provider}`
                };
            }

            // Create a userApiKeys map with the test key
            const testApiKeys = new Map<string, string>();
            testApiKeys.set(provider, apiKey);

            // Create test message using core abstractions
            const testMessage = createUserMessage('Test connection. Please respond with "OK".');

            // Use core inference system to test the provider key
            const response = await infer({
                env: this.env,
                metadata: { agentId: `provider-test-${Date.now()}`, userId: 'system' }, // Generate unique test ID
                messages: [testMessage],
                modelName: testModel,
                maxTokens: 10,
                temperature: 0,
                actionKey: 'testModelConfig',
                userApiKeys: Object.fromEntries(testApiKeys)
            });

            const endTime = Date.now();
            const cleanModelName = testModel.replace(/\[.*?\]/, '');

            if (response.string && response.string.trim()) {
                return {
                    success: true,
                    model: cleanModelName,
                    latencyMs: endTime - startTime
                };
            } else {
                return {
                    success: false,
                    error: 'No response received from model'
                };
            }

        } catch (error: unknown) {
            const endTime = Date.now();
            const latencyMs = endTime - startTime;

            // Handle InferError and other errors from core system
            let rawError = 'Connection test failed';

            if (error instanceof InferError) {
                rawError = error.message;
            } else if (error instanceof Error) {
                rawError = error.message;
            } else if (isErrorWithMessage(error)) {
                // Handle error objects from the core system
                if (error.message) {
                    rawError = error.message;
                } else if (error.error?.message) {
                    rawError = error.error.message;
                } else {
                    rawError = JSON.stringify(error);
                }
            } else {
                rawError = String(error);
            }

            return {
                success: false,
                error: rawError,
                latencyMs
            };
        }
    }

    /**
     * Get a simple test model for a given provider
     */
    private getTestModelForProvider(provider: string): string | null {
        const testModels: Record<string, string> = {
            'openai': AIModels.OPENAI_5_MINI,
            'anthropic': AIModels.CLAUDE_4_SONNET,
            'google-ai-studio': AIModels.GEMINI_2_5_FLASH,
            'gemini': AIModels.GEMINI_2_5_FLASH,
            // 'openrouter': AIModels.OPENROUTER_QWEN_3_CODER, // Removed - not available
            'cerebras': AIModels.CEREBRAS_GPT_OSS
        };

        return testModels[provider] || null;
    }
}

import { TemplateDetails } from "../../services/sandbox/sandboxTypes";
import { SetupCommandsType, type Blueprint } from "../schemas";
import { createObjectLogger, StructuredLogger } from '../../logger';
import { generalSystemPromptBuilder, PROMPT_UTILS } from '../prompts';
import { createAssistantMessage, createSystemMessage, createUserMessage } from "../inferutils/common";
import { executeInference, } from "../inferutils/infer";
import Assistant from "./assistant";
import { AIModels, InferenceContext } from "../inferutils/config.types";
import { extractCommands } from "../utils/common";

interface GenerateSetupCommandsArgs {
    env: Env;
    agentId: string;
    query: string;
    blueprint: Blueprint;
    template: TemplateDetails;
    inferenceContext: InferenceContext;
}

const SYSTEM_PROMPT = `You are an Expert DevOps Engineer at Cloudflare specializing in project setup and dependency management. Your task is to analyze project requirements and generate precise installation commands for missing dependencies.`

const SETUP_USER_PROMPT = `## TASK
Analyze the blueprint and generate exact \`bun add\` commands for missing dependencies. Only suggest packages that are NOT already in the starting template.

## EXAMPLES

**Example 1 - Game Project:**
Blueprint mentions: "2D Canvas game with score persistence"
Starting template has: react, typescript, tailwindcss
Output:
\`\`\`bash
bun add zustand@^4.5.0
bun add canvas-confetti@^1.9.0
\`\`\`

**Example 2 - Dashboard with Charts:**
Blueprint mentions: "Analytics dashboard with interactive charts"
Starting template has: react, typescript, vite
Output:
\`\`\`bash
bun add recharts@^2.12.0
bun add date-fns@^3.6.0
bun add @headlessui/react@^2.0.0
\`\`\`

**Example 3 - Already Complete:**
Blueprint mentions: "Simple todo app"
Starting template has: react, typescript, tailwindcss, lucide-react
Output:
\`\`\`bash
# No additional dependencies needed
\`\`\`

## RULES
- Use ONLY \`bun add\` commands
- Include specific version constraints (e.g., ^4.5.0)
- Check version compatibility (React 18 vs 19)
- Skip dependencies already in starting template
- Include common companion packages when needed
- Focus on blueprint requirements only

${PROMPT_UTILS.COMMANDS}

<INPUT DATA>
<QUERY>
{{query}}
</QUERY>

<BLUEPRINT>
{{blueprint}}
</BLUEPRINT>

<STARTING TEMPLATE>
{{template}}

These are the only dependencies installed currently
{{dependencies}}
</STARTING TEMPLATE>

You need to make sure **ALL THESE** are installed at the least:
{{blueprintDependencies}}

</INPUT DATA>`;

export class ProjectSetupAssistant extends Assistant<Env> {
    private query: string;
    private logger: StructuredLogger;

    constructor({
        env,
        inferenceContext,
        query,
        blueprint,
        template,
    }: GenerateSetupCommandsArgs) {
        const systemPrompt = createSystemMessage(SYSTEM_PROMPT);
        super(env, inferenceContext, systemPrompt);
        this.save([createUserMessage(generalSystemPromptBuilder(SETUP_USER_PROMPT, {
            query,
            blueprint,
            templateDetails: template,
            dependencies: template.deps,
        }))]);
        this.query = query;
        this.logger = createObjectLogger(this, 'ProjectSetupAssistant')
    }

    async generateSetupCommands(error?: string): Promise<SetupCommandsType> {
        this.logger.info("Generating setup commands", { query: this.query, queryLength: this.query.length });

        try {
            let userPrompt = createUserMessage(`Now please suggest required setup commands for the project, inside markdown code fence`);
            if (error) {
                this.logger.info(`Regenerating setup commands after error: ${error}`);
                userPrompt = createUserMessage(`Some of the previous commands you generated might not have worked. Please review these and generate new commands if required, maybe try a different version or correct the name?
If the package simply doesn't exist, please don't suggest it. 

${error}`);
                this.logger.info(`Regenerating setup commands with new prompt: ${userPrompt.content}`);
            }
            const messages = this.save([userPrompt]);

            const results = await executeInference({
                env: this.env,
                messages,
                agentActionName: "projectSetup",
                context: this.inferenceContext,
                modelName: error? AIModels.GEMINI_2_5_FLASH : undefined,
            });
            if (!results || typeof results !== 'string') {
                this.logger.info(`Failed to generate setup commands, results: `, { results });
                return { commands: [] };
            }

            this.logger.info(`Generated setup commands: ${results}`);

            this.save([createAssistantMessage(results)]);
            return { commands: extractCommands(results) };
        } catch (error) {
            this.logger.error("Error generating setup commands:", error);
            throw error;
        }
    }
}

/**
 * Secrets Routes
 * API routes for user secrets management
 */

import { SecretsController } from '../controllers/secrets/controller';
import { Hono } from 'hono';
import { AppEnv } from '../../types/appenv';
import { adaptController } from '../honoAdapter';
import { AuthConfig, setAuthLevel } from '../../middleware/auth/routeAuth';

/**
 * Setup secrets-related routes
 */
export function setupSecretsRoutes(app: Hono<AppEnv>): void {
    // Create a sub-router for secrets routes
    const secretsRouter = new Hono<AppEnv>();

    // Secrets management routes
    secretsRouter.get('/', setAuthLevel(AuthConfig.authenticated), adaptController(SecretsController, SecretsController.getAllSecrets));

    // DISABLED: BYOK Disabled for security reasons
    // secretsRouter.post('/', setAuthLevel(AuthConfig.authenticated), adaptController(SecretsController, SecretsController.storeSecret));
    secretsRouter.post('/', setAuthLevel(AuthConfig.authenticated), (c) => {
        return c.json({ message: 'BYOK is not supported for now' });
    });
    // secretsRouter.patch('/:secretId/toggle', setAuthLevel(AuthConfig.authenticated), adaptController(SecretsController, SecretsController.toggleSecret));
    // secretsRouter.delete('/:secretId', setAuthLevel(AuthConfig.authenticated), adaptController(SecretsController, SecretsController.deleteSecret));

    // Templates route
    secretsRouter.get('/templates', setAuthLevel(AuthConfig.authenticated), adaptController(SecretsController, SecretsController.getTemplates));

    // Mount the router under /api/secrets
    app.route('/api/secrets', secretsRouter);
}

/**
 * Authentication Routes
 */
import { AuthController } from '../controllers/auth/controller';
import { Hono } from 'hono';
import { AppEnv } from '../../types/appenv';
import { adaptController } from '../honoAdapter';
import { AuthConfig, setAuthLevel } from '../../middleware/auth/routeAuth';

/**
 * Setup authentication routes
 */
export function setupAuthRoutes(app: Hono<AppEnv>): void {
    // Create a sub-router for auth routes
    const authRouter = new Hono<AppEnv>();

    // Public authentication routes
    authRouter.get('/csrf-token', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.getCsrfToken));
    authRouter.get('/providers', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.getAuthProviders));
    authRouter.post('/register', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.register));
    authRouter.post('/login', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.login));
    authRouter.post('/verify-email', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.verifyEmail));
    authRouter.post('/resend-verification', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.resendVerificationOtp));
    authRouter.get('/check', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.checkAuth));

    // Protected routes (require authentication) - must come before dynamic OAuth routes
    authRouter.get('/profile', setAuthLevel(AuthConfig.authenticated), adaptController(AuthController, AuthController.getProfile));
    authRouter.put('/profile', setAuthLevel(AuthConfig.authenticated), adaptController(AuthController, AuthController.updateProfile));
    authRouter.post('/logout', setAuthLevel(AuthConfig.authenticated), adaptController(AuthController, AuthController.logout));

    // Session management routes
    authRouter.get('/sessions', setAuthLevel(AuthConfig.authenticated), adaptController(AuthController, AuthController.getActiveSessions));
    authRouter.delete('/sessions/:sessionId', setAuthLevel(AuthConfig.authenticated), adaptController(AuthController, AuthController.revokeSession));

    // // API Keys management routes
    // authRouter.get('/api-keys', createHandler('getApiKeys'), AuthConfig.authenticated);
    // authRouter.post('/api-keys', createHandler('createApiKey'), AuthConfig.authenticated);
    // authRouter.delete('/api-keys/:keyId', createHandler('revokeApiKey'), AuthConfig.authenticated);

    // OAuth routes (under /oauth path to avoid conflicts)
    authRouter.get('/oauth/:provider', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.initiateOAuth));
    authRouter.get('/callback/:provider', setAuthLevel(AuthConfig.public), adaptController(AuthController, AuthController.handleOAuthCallback));

    // Mount the auth router under /api/auth
    app.route('/api/auth', authRouter);
}

/**
 * Authentication Validation Schemas
 * Zod schemas for validating auth-related requests
 */

import { z } from 'zod';
import { commonSchemas } from '../../../utils/inputValidator';

/**
 * Login request schema
 */
export const loginSchema = z.object({
  email: commonSchemas.email,
  password: z.string().min(1, 'Password is required')
});

export type LoginRequest = z.infer<typeof loginSchema>;

/**
 * Registration request schema
 */
export const registerSchema = z.object({
  email: commonSchemas.email,
  password: commonSchemas.password,
  name: z.string().min(2, 'Name must be at least 2 characters').max(100).optional()
});

export type RegisterRequest = z.infer<typeof registerSchema>;

/**
 * OAuth callback schema
 */
export const oauthCallbackSchema = z.object({
  code: z.string().min(1, 'Authorization code is required'),
  state: z.string().min(1, 'State is required'),
  error: z.string().optional(),
  error_description: z.string().optional()
});

export type OAuthCallbackRequest = z.infer<typeof oauthCallbackSchema>;

/**
 * Change password schema
 */
export const changePasswordSchema = z.object({
  currentPassword: z.string().min(1, 'Current password is required'),
  newPassword: commonSchemas.password,
  confirmPassword: z.string()
}).refine(data => data.newPassword === data.confirmPassword, {
  message: "Passwords don't match",
  path: ['confirmPassword']
});

export type ChangePasswordRequest = z.infer<typeof changePasswordSchema>;

/**
 * Forgot password schema
 */
export const forgotPasswordSchema = z.object({
  email: commonSchemas.email
});

export type ForgotPasswordRequest = z.infer<typeof forgotPasswordSchema>;

/**
 * Reset password schema
 */
export const resetPasswordSchema = z.object({
  token: z.string().min(1, 'Reset token is required'),
  newPassword: commonSchemas.password,
  confirmPassword: z.string()
}).refine(data => data.newPassword === data.confirmPassword, {
  message: "Passwords don't match",
  path: ['confirmPassword']
});

export type ResetPasswordRequest = z.infer<typeof resetPasswordSchema>;

/**
 * Verify email schema
 */
export const verifyEmailSchema = z.object({
  token: z.string().min(1, 'Verification token is required')
});

export type VerifyEmailRequest = z.infer<typeof verifyEmailSchema>;

/**
 * OAuth provider schema
 */
export const oauthProviderSchema = z.enum(['google', 'github']);

export type OAuthProviderParam = z.infer<typeof oauthProviderSchema>;

/**
 * Type definitions for Secrets Controller responses
 */

