            const byokTemplates = getBYOKTemplates();

            // Get all user secrets
            const secrets = await this.database
                .select()
                .from(schema.userSecrets)
                .where(
                    and(
                        eq(schema.userSecrets.userId, userId),
                        eq(schema.userSecrets.isActive, true)
