/**
 * Model Providers Service
 */

import { BaseService } from './BaseService';
import * as schema from '../schema';
import { eq, and, sql } from 'drizzle-orm';
import { generateId } from '../../utils/idGenerator';

export interface CreateProviderData {
    name: string;
    baseUrl: string;
    secretId: string;
}

export interface UpdateProviderData {
    name?: string;
    baseUrl?: string;
    secretId?: string | null;
    isActive?: boolean;
}

export class ModelProvidersService extends BaseService {
    /**
     * Check if provider name exists for user
     */
    async providerExists(userId: string, name: string): Promise<boolean> {
        const existing = await this.database
            .select()
            .from(schema.userModelProviders)
            .where(
                and(
                    eq(schema.userModelProviders.userId, userId),
                    eq(schema.userModelProviders.name, name)
                )
            )
            .get();

        return !!existing;
    }

    /**
     * Create a new model provider
     */
    async createProvider(userId: string, data: CreateProviderData): Promise<schema.UserModelProvider> {
        const providerId = generateId();
        const provider = {
            id: providerId,
            userId,
            name: data.name,
            baseUrl: data.baseUrl,
            secretId: data.secretId,
            isActive: true,
            createdAt: new Date(),
            updatedAt: new Date()
        };

        const [created] = await this.database
            .insert(schema.userModelProviders)
            .values(provider)
            .returning();

        return created;
    }

    /**
     * Get all providers for a user
     */
    async getUserProviders(userId: string): Promise<schema.UserModelProvider[]> {
        return await this.database
            .select()
            .from(schema.userModelProviders)
            .where(eq(schema.userModelProviders.userId, userId))
            .all();
    }

    /**
     * Get a specific provider by ID
     */
    async getProvider(userId: string, providerId: string): Promise<schema.UserModelProvider | null> {
        const provider = await this.database
            .select()
            .from(schema.userModelProviders)
            .where(
                and(
                    eq(schema.userModelProviders.id, providerId),
                    eq(schema.userModelProviders.userId, userId)
                )
            )
            .get();

        return provider || null;
    }

    /**
     * Get a provider by name
     */
    async getProviderByName(userId: string, name: string): Promise<schema.UserModelProvider | null> {
        const provider = await this.database
            .select()
            .from(schema.userModelProviders)
            .where(
                and(
                    eq(schema.userModelProviders.userId, userId),
                    eq(schema.userModelProviders.name, name)
                )
            )
            .get();

        return provider || null;
    }

    /**
     * Update a provider
     */
    async updateProvider(
        userId: string, 
        providerId: string, 
        data: UpdateProviderData
    ): Promise<schema.UserModelProvider | null> {
        const updateData: Partial<typeof schema.userModelProviders.$inferInsert> = {
            ...data,
            updatedAt: new Date()
        };

        const [updated] = await this.database
            .update(schema.userModelProviders)
            .set(updateData)
            .where(
                and(
                    eq(schema.userModelProviders.id, providerId),
                    eq(schema.userModelProviders.userId, userId)
                )
            )
            .returning();

        return updated || null;
    }

    /**
     * Delete a provider
     */
    async deleteProvider(userId: string, providerId: string): Promise<boolean> {
        const result = await this.database
            .delete(schema.userModelProviders)
            .where(
                and(
                    eq(schema.userModelProviders.id, providerId),
                    eq(schema.userModelProviders.userId, userId)
                )
            )
            .returning();

        return result.length > 0;
    }

    /**
     * Toggle provider active status
     */
    async toggleProviderStatus(userId: string, providerId: string): Promise<schema.UserModelProvider | null> {
        const provider = await this.getProvider(userId, providerId);
        if (!provider) {
            return null;
        }

        return await this.updateProvider(userId, providerId, {
            isActive: !provider.isActive
        });
    }

    /**
     * Get provider count for user
     */
    async getProviderCount(userId: string): Promise<number> {
        const result = await this.database
            .select({ count: sql<number>`count(*)` })
            .from(schema.userModelProviders)
            .where(eq(schema.userModelProviders.userId, userId))
            .get();

        return result?.count || 0;
    }
}

/**
 * Model Configuration Service
 * Handles CRUD operations for user model configurations
 */

import { BaseService } from './BaseService';
import { UserModelConfig, NewUserModelConfig, userModelConfigs } from '../schema';
import { eq, and } from 'drizzle-orm';
import { AgentActionKey, ModelConfig, AIModels } from '../../agents/inferutils/config.types';
import { AGENT_CONFIG } from '../../agents/inferutils/config';
import type { ReasoningEffort } from 'openai/resources.mjs';
import { generateId } from '../../utils/idGenerator';
import type { UserModelConfigWithMetadata } from '../types';

export class ModelConfigService extends BaseService {
    /**
     * Safely cast database string to ReasoningEffort type
     */
    private castToReasoningEffort(value: string | null): ReasoningEffort | undefined {
        if (!value) return undefined;
        return value as ReasoningEffort;
    }

    /**
     * Get all model configurations for a user (merged with defaults)
     */
    async getUserModelConfigs(userId: string): Promise<Record<AgentActionKey, UserModelConfigWithMetadata>> {
        const userConfigs = await this.database
            .select()
            .from(userModelConfigs)
            .where(and(
                eq(userModelConfigs.userId, userId),
                eq(userModelConfigs.isActive, true)
            ));

        const result: Record<string, UserModelConfigWithMetadata> = {};

        // Start with all default configurations
        for (const [actionKey, defaultConfig] of Object.entries(AGENT_CONFIG)) {
            const userConfig = userConfigs.find((uc: UserModelConfig) => uc.agentActionName === actionKey);

            if (userConfig) {
                // Merge user config with defaults (user config takes precedence, null values use defaults)
                result[actionKey] = {
                    name: (userConfig.modelName as AIModels) ?? defaultConfig.name,
                    max_tokens: userConfig.maxTokens ?? defaultConfig.max_tokens,
                    temperature: userConfig.temperature !== null ? userConfig.temperature : defaultConfig.temperature,
                    reasoning_effort: this.castToReasoningEffort(userConfig.reasoningEffort) ?? defaultConfig.reasoning_effort,
                    fallbackModel: (userConfig.fallbackModel as AIModels) ?? defaultConfig.fallbackModel,
                    isUserOverride: true,
                    userConfigId: userConfig.id
                };
            } else {
                // Use default config
                result[actionKey] = {
                    ...defaultConfig,
                    isUserOverride: false
                };
            }
        }

        return result as Record<AgentActionKey, UserModelConfigWithMetadata>;
    }

    /**
     * Get a specific model configuration for a user (merged with defaults for UI display)
     */
    async getUserModelConfig(userId: string, agentActionName: AgentActionKey): Promise<UserModelConfigWithMetadata> {
        const userConfig = await this.database
            .select()
            .from(userModelConfigs)
            .where(and(
                eq(userModelConfigs.userId, userId),
                eq(userModelConfigs.agentActionName, agentActionName),
                eq(userModelConfigs.isActive, true)
            ))
            .limit(1);

        const defaultConfig = AGENT_CONFIG[agentActionName];

        if (userConfig.length > 0) {
            const config = userConfig[0];
            return {
                name: (config.modelName as AIModels) ?? defaultConfig.name,
                max_tokens: config.maxTokens ?? defaultConfig.max_tokens,
                temperature: config.temperature !== null ? config.temperature : defaultConfig.temperature,
                reasoning_effort: this.castToReasoningEffort(config.reasoningEffort) ?? defaultConfig.reasoning_effort,
                fallbackModel: (config.fallbackModel as AIModels) ?? defaultConfig.fallbackModel,
                isUserOverride: true,
                userConfigId: config.id
            };
        }

        return {
            ...defaultConfig,
            isUserOverride: false
        };
    }

    /**
     * Get raw user model configuration without merging with defaults
     * Returns null if user has no custom config (for executeInference usage)
     */
    async getRawUserModelConfig(userId: string, agentActionName: AgentActionKey): Promise<ModelConfig | null> {
        const userConfig = await this.database
            .select()
            .from(userModelConfigs)
            .where(and(
                eq(userModelConfigs.userId, userId),
                eq(userModelConfigs.agentActionName, agentActionName),
                eq(userModelConfigs.isActive, true)
            ))
            .limit(1);

        if (userConfig.length > 0) {
            const config = userConfig[0];

            // Only create ModelConfig if user has actual overrides
            const hasOverrides = config.modelName || config.maxTokens || 
                                config.temperature !== null || config.reasoningEffort || 
                                config.fallbackModel;

            if (hasOverrides) {
                const defaultConfig = AGENT_CONFIG[agentActionName];
                const modelConfig: ModelConfig = {
                    name: (config.modelName as AIModels) || defaultConfig.name,
                    max_tokens: config.maxTokens || defaultConfig.max_tokens,
                    temperature: config.temperature !== null ? config.temperature : defaultConfig.temperature,
                    reasoning_effort: this.castToReasoningEffort(config.reasoningEffort) ?? defaultConfig.reasoning_effort,
                    fallbackModel: (config.fallbackModel as AIModels) || defaultConfig.fallbackModel,
                };
                return modelConfig;
            }
        }

        // Return null if user has no custom config - let AGENT_CONFIG defaults rule
        return null;
    }

    /**
     * Update or create a user model configuration
     */
    async upsertUserModelConfig(
        userId: string,
        agentActionName: AgentActionKey,
        config: Partial<ModelConfig>
    ): Promise<UserModelConfig> {
        const existingConfig = await this.database
            .select()
            .from(userModelConfigs)
            .where(and(
                eq(userModelConfigs.userId, userId),
                eq(userModelConfigs.agentActionName, agentActionName)
            ))
            .limit(1);

        const configData: Partial<NewUserModelConfig> = {
            userId,
            agentActionName,
            modelName: config.name || null,
            maxTokens: config.max_tokens || null,
            temperature: config.temperature !== undefined ? config.temperature : null,
            reasoningEffort: (config.reasoning_effort && config.reasoning_effort !== 'minimal') ? config.reasoning_effort : null,
            fallbackModel: config.fallbackModel || null,
            isActive: true,
            updatedAt: new Date()
        };

        if (existingConfig.length > 0) {
            // Update existing config
            const updated = await this.database
                .update(userModelConfigs)
                .set(configData)
                .where(eq(userModelConfigs.id, existingConfig[0].id))
                .returning();

            return updated[0];
        } else {
            // Create new config
            const newConfig: NewUserModelConfig = {
                id: generateId(),
                ...configData,
                createdAt: new Date()
            } as NewUserModelConfig;

            const created = await this.database
                .insert(userModelConfigs)
                .values(newConfig)
                .returning();

            return created[0];
        }
    }

    /**
     * Delete/reset a user model configuration (revert to default)
     */
    async deleteUserModelConfig(userId: string, agentActionName: AgentActionKey): Promise<boolean> {
        const result = await this.database
            .delete(userModelConfigs)
            .where(and(
                eq(userModelConfigs.userId, userId),
                eq(userModelConfigs.agentActionName, agentActionName)
            ));

        return (result.meta?.changes || 0) > 0;
    }

    /**
     * Get default configurations (from AGENT_CONFIG)
     */
    getDefaultConfigs(): Record<AgentActionKey, ModelConfig> {
        return AGENT_CONFIG;
    }

    /**
     * Reset all user configurations to defaults
     */
    async resetAllUserConfigs(userId: string): Promise<number> {
        const result = await this.database
            .delete(userModelConfigs)
            .where(eq(userModelConfigs.userId, userId));

        return result.meta?.changes || 0;
    }
}

/**
 * API Key Service
 * Handles all API key-related database operations
 */

import { BaseService } from './BaseService';
import * as schema from '../schema';
import { eq, and, desc, sql } from 'drizzle-orm';
import { generateId } from '../../utils/idGenerator';
import { createLogger } from '../../logger';

const logger = createLogger('ApiKeyService');

export interface ApiKeyInfo {
    id: string;
    name: string;
    keyPreview: string;
    createdAt: Date | null;
    lastUsed?: Date | null;
    isActive: boolean | null;
}

export interface CreateApiKeyData {
    userId: string;
    name: string;
    keyHash: string;
    keyPreview: string;
}

/**
 * API Key Service for managing API keys
 */
export class ApiKeyService extends BaseService {

    /**
     * Get all API keys for a user
     */
    async getUserApiKeys(userId: string): Promise<ApiKeyInfo[]> {
        try {
            const keys = await this.database
                .select({
                    id: schema.apiKeys.id,
                    name: schema.apiKeys.name,
                    keyPreview: schema.apiKeys.keyPreview,
                    createdAt: schema.apiKeys.createdAt,
                    lastUsed: schema.apiKeys.lastUsed,
                    isActive: schema.apiKeys.isActive
                })
                .from(schema.apiKeys)
                .where(eq(schema.apiKeys.userId, userId))
                .orderBy(desc(schema.apiKeys.createdAt))
                .all();

            return keys;
        } catch (error) {
            logger.error('Error fetching user API keys', error);
            return [];
        }
    }

    /**
     * Create a new API key
     */
    async createApiKey(data: CreateApiKeyData): Promise<string> {
        try {
            const keyId = generateId();

            await this.database.insert(schema.apiKeys).values({
                id: keyId,
                userId: data.userId,
                name: data.name,
                keyHash: data.keyHash,
                keyPreview: data.keyPreview,
                scopes: JSON.stringify([]),
                createdAt: new Date(),
                updatedAt: new Date(),
                isActive: true
            });

            logger.info('API key created', { keyId, userId: data.userId });

            return keyId;
        } catch (error) {
            logger.error('Error creating API key', error);
            throw new Error('Failed to create API key');
        }
    }

    /**
     * Revoke an API key
     */
    async revokeApiKey(keyId: string, userId: string): Promise<boolean> {
        try {
            await this.database
                .update(schema.apiKeys)
                .set({
                    isActive: false,
                    updatedAt: new Date()
                })
                .where(
                    and(
                        eq(schema.apiKeys.id, keyId),
                        eq(schema.apiKeys.userId, userId)
                    )
                );

            logger.info('API key revoked', { keyId, userId });

            return true;
        } catch (error) {
            logger.error('Error revoking API key', error);
            return false;
        }
    }

    /**
     * Find API key by hash
     */
    async findApiKeyByHash(keyHash: string): Promise<schema.ApiKey | null> {
        try {
            const key = await this.database
                .select()
                .from(schema.apiKeys)
                .where(
                    and(
                        eq(schema.apiKeys.keyHash, keyHash),
                        eq(schema.apiKeys.isActive, true)
                    )
                )
                .get();

            return key || null;
        } catch (error) {
            logger.error('Error finding API key by hash', error);
            return null;
        }
    }

    /**
     * Update API key last used time
     */
    async updateApiKeyLastUsed(keyId: string): Promise<void> {
        try {
            await this.database
                .update(schema.apiKeys)
                .set({
                    lastUsed: new Date(),
                    updatedAt: new Date()
                })
                .where(eq(schema.apiKeys.id, keyId));
        } catch (error) {
            logger.error('Error updating API key last used', error);
        }
    }

    /**
     * Check if API key name is unique for user
     */
    async isApiKeyNameUnique(userId: string, name: string): Promise<boolean> {
        try {
            const existing = await this.database
                .select({ id: schema.apiKeys.id })
                .from(schema.apiKeys)
                .where(
                    and(
                        eq(schema.apiKeys.userId, userId),
                        eq(schema.apiKeys.name, name),
                        eq(schema.apiKeys.isActive, true)
                    )
                )
                .get();

            return !existing;
        } catch (error) {
            logger.error('Error checking API key name uniqueness', error);
            return false;
        }
    }

    /**
     * Get active API key count for user
     */
    async getActiveApiKeyCount(userId: string): Promise<number> {
        try {
            const result = await this.database
                .select({ count: sql<number>`COUNT(*)` })
                .from(schema.apiKeys)
                .where(
                    and(
                        eq(schema.apiKeys.userId, userId),
                        eq(schema.apiKeys.isActive, true)
                    )
                )
                .get();

            return Number(result?.count) || 0;
        } catch (error) {
            logger.error('Error counting active API keys', error);
            return 0;
        }
    }
}

/**
 * Comprehensive tests for XmlStreamFormat
 * Tests streaming parsing, error handling, fallback logic, and edge cases
 */

import { XmlStreamFormat, XmlStreamingCallbacks } from './xml-stream';

describe('XmlStreamFormat', () => {
    let parser: XmlStreamFormat;
    let mockCallbacks: jest.Mocked<XmlStreamingCallbacks>;

    beforeEach(() => {
        parser = new XmlStreamFormat();
        mockCallbacks = {
            onElementStart: jest.fn(),
            onElementContent: jest.fn(),
            onElementComplete: jest.fn(),
            onParsingError: jest.fn(),
        };
    });

    describe('Basic XML Parsing', () => {
        test('should parse simple XML elements', () => {
            const xml = '<user_response>Hello world</user_response>';
            const config = { targetElements: ['user_response'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            const userResponse = elements.get('user_response');
            expect(userResponse).toBeDefined();
            expect(userResponse![0].content).toBe('Hello world');
            expect(userResponse![0].isComplete).toBe(true);
        });

        test('should parse multiple elements', () => {
            const xml = `
                <user_response>Response here</user_response>
                <enhanced_user_request>Enhanced request</enhanced_user_request>
            `;
            const config = { targetElements: ['user_response', 'enhanced_user_request'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            expect(elements.get('user_response')![0].content.trim()).toBe('Response here');
            expect(elements.get('enhanced_user_request')![0].content.trim()).toBe('Enhanced request');
        });

        test('should parse elements with attributes', () => {
            const xml = '<element id="123" class="test">Content</element>';
            const config = { targetElements: ['element'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            const element = elements.get('element')![0];
            expect(element.attributes.id).toBe('123');
            expect(element.attributes.class).toBe('test');
            expect(element.content).toBe('Content');
        });

        test('should handle self-closing tags', () => {
            const xml = '<empty_element id="test" />';
            const config = { targetElements: ['empty_element'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            const element = elements.get('empty_element')![0];
            expect(element.attributes.id).toBe('test');
            expect(element.content).toBe('');
            expect(element.isComplete).toBe(true);
        });
    });

    describe('Streaming Functionality', () => {
        test('should stream element content in real-time', () => {
            const config = { 
                targetElements: ['user_response'], 
                streamingElements: ['user_response'] 
            };
            let state = parser.initializeXmlState(config);

            // Stream opening tag and partial content
            state = parser.parseXmlStream('<user_response>Hello', state, mockCallbacks, config);
            expect(mockCallbacks.onElementContent).toHaveBeenCalledWith('user_response', 'Hello', false);

            // Stream more content
            state = parser.parseXmlStream(' world', state, mockCallbacks, config);
            expect(mockCallbacks.onElementContent).toHaveBeenCalledWith('user_response', ' world', false);

            // Stream closing tag
            state = parser.parseXmlStream('</user_response>', state, mockCallbacks, config);
            expect(mockCallbacks.onElementComplete).toHaveBeenCalled();
        });

        test('should handle chunked XML tags', () => {
            const config = { targetElements: ['test'] };
            let state = parser.initializeXmlState(config);

            // Tag split across chunks
            state = parser.parseXmlStream('<te', state, mockCallbacks, config);
            state = parser.parseXmlStream('st>Content</te', state, mockCallbacks, config);
            state = parser.parseXmlStream('st>', state, mockCallbacks, config);

            const elements = parser.finalizeXmlParsing(state);
            expect(elements.get('test')![0].content).toBe('Content');
        });

        test('should handle large content chunks', () => {
            const largeContent = 'x'.repeat(5000);
            const xml = `<large_element>${largeContent}</large_element>`;
            const config = { targetElements: ['large_element'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            expect(elements.get('large_element')![0].content).toBe(largeContent);
        });
    });

    describe('Error Handling and Fallback', () => {
        test('should handle malformed XML gracefully', () => {
            const malformedXml = '<user_response>Content without closing tag';
            const config = { targetElements: ['user_response'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(malformedXml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            // Should still extract content via fallback
            expect(elements.get('user_response')).toBeDefined();
            expect(state.hasParsingErrors).toBe(false); // Fallback handles this gracefully
        });

        test('should handle mismatched tags', () => {
            const mismatchedXml = '<user_response>Content</wrong_tag>';
            const config = { targetElements: ['user_response'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(mismatchedXml, state, mockCallbacks, config);

            expect(mockCallbacks.onParsingError).toHaveBeenCalled();
            expect(state.hasParsingErrors).toBe(true);
        });

        test('should handle empty input', () => {
            const config = { targetElements: ['test'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream('', state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            expect(elements.size).toBe(0);
            expect(state.hasParsingErrors).toBe(false);
        });

        test('should handle XML with no target elements', () => {
            const xml = '<other_element>Content</other_element>';
            const config = { targetElements: ['user_response'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            expect(elements.get('user_response')).toBeUndefined();
            expect(elements.get('other_element')).toBeUndefined();
        });

        test('should use fallback extraction for malformed content', () => {
            const malformedXml = '<user_response>Good content</user_response><enhanced_user_request>Also good';
            const config = { targetElements: ['user_response', 'enhanced_user_request'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(malformedXml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            expect(elements.get('user_response')![0].content).toBe('Good content');
            expect(elements.get('enhanced_user_request')![0].content).toBe('Also good');
        });
    });

    describe('Buffer Management', () => {
        test('should limit buffer size to prevent memory issues', () => {
            const hugeContent = 'x'.repeat(20000);
            const config = { 
                targetElements: ['test'], 
                maxBufferSize: 5000 
            };
            let state = parser.initializeXmlState(config);

            // This should not cause memory issues
            state = parser.parseXmlStream(hugeContent, state, mockCallbacks, config);

            // Buffer should be limited
            expect(state.contentBuffer.length).toBeLessThan(15000);
        });

        test('should handle partial XML tags at buffer boundaries', () => {
            const config = { targetElements: ['test'] };
            let state = parser.initializeXmlState(config);

            // Add content that ends with partial tag
            const contentWithPartialTag = 'some content <tes';
            state = parser.parseXmlStream(contentWithPartialTag, state, mockCallbacks, config);

            // Complete the tag
            state = parser.parseXmlStream('t>Final content</test>', state, mockCallbacks, config);

            const elements = parser.finalizeXmlParsing(state);
            expect(elements.get('test')![0].content).toBe('Final content');
        });
    });

    describe('Configuration Options', () => {
        test('should respect case sensitivity setting', () => {
            const xml = '<USER_RESPONSE>Content</USER_RESPONSE>';

            // Case insensitive (default)
            const insensitiveConfig = { 
                targetElements: ['user_response'],
                caseSensitive: false 
            };
            let state1 = parser.initializeXmlState(insensitiveConfig);
            state1 = parser.parseXmlStream(xml, state1, mockCallbacks, insensitiveConfig);
            const elements1 = parser.finalizeXmlParsing(state1);

            expect(elements1.get('user_response')).toBeDefined();

            // Case sensitive
            const sensitiveConfig = { 
                targetElements: ['user_response'],
                caseSensitive: true 
            };
            let state2 = parser.initializeXmlState(sensitiveConfig);
            state2 = parser.parseXmlStream(xml, state2, mockCallbacks, sensitiveConfig);
            const elements2 = parser.finalizeXmlParsing(state2);

            expect(elements2.get('user_response')).toBeUndefined();
        });

        test('should only extract target elements when specified', () => {
            const xml = `
                <user_response>Response</user_response>
                <enhanced_user_request>Request</enhanced_user_request>
                <other_element>Other</other_element>
            `;

            const config = { targetElements: ['user_response'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            expect(elements.get('user_response')).toBeDefined();
            expect(elements.get('enhanced_user_request')).toBeUndefined();
            expect(elements.get('other_element')).toBeUndefined();
        });

        test('should extract all elements when no targets specified', () => {
            const xml = `
                <element1>Content1</element1>
                <element2>Content2</element2>
            `;

            const config = {}; // No target elements = extract all
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            expect(elements.get('element1')).toBeDefined();
            expect(elements.get('element2')).toBeDefined();
        });
    });

    describe('Nested Elements', () => {
        test('should handle simple nested elements', () => {
            const xml = '<parent><child>Child content</child>Parent content</parent>';
            const config = { targetElements: ['parent'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            const parent = elements.get('parent')![0];
            expect(parent.children).toHaveLength(1);
            expect(parent.children[0].tagName).toBe('child');
            expect(parent.children[0].content).toBe('Child content');
        });

        test('should handle deeply nested elements', () => {
            const xml = `
                <level1>
                    <level2>
                        <level3>Deep content</level3>
                    </level2>
                </level1>
            `;
            const config = { targetElements: ['level1'] };
            let state = parser.initializeXmlState(config);

            state = parser.parseXmlStream(xml, state, mockCallbacks, config);
            const elements = parser.finalizeXmlParsing(state);

            const level1 = elements.get('level1')![0];
