that will be
completely replaced`;

    const diff = `--- a/file.txt
+++ b/file.txt
@@ -1,3 +1,2 @@
-old content
-that will be
-completely replaced
+brand new content
+with different structure`;

    const expected = `brand new content
with different structure`;

    const result = applyUnifiedDiff(original, diff);
    expect(result).toBe(expected);
  });

  it('should preserve whitespace and indentation', () => {
    const original = `def function():
    if True:
        print("indented")
    return None`;

    const diff = `--- a/file.py
+++ b/file.py
@@ -1,4 +1,5 @@
 def function():
     if True:
         print("indented")
+        print("another indented line")
     return None`;

    const expected = `def function():
    if True:
        print("indented")
        print("another indented line")
    return None`;

    const result = applyUnifiedDiff(original, diff);
    expect(result).toBe(expected);
  });

  it('should handle Windows line endings', () => {
    const original = 'line 1\r\nline 2\r\nline 3';

    const diff = `--- a/file.txt
+++ b/file.txt
@@ -1,3 +1,3 @@
 line 1
-line 2
+modified line 2
 line 3`;

    const expected = 'line 1\r\nmodified line 2\r\nline 3';

    const result = applyUnifiedDiff(original, diff);
    expect(result).toBe(expected);
  });

  it('should handle context lines correctly', () => {
    const original = `a
b
c
d
e
f
g`;

    const diff = `--- a/file.txt
+++ b/file.txt
@@ -2,5 +2,5 @@ a
 b
 c
-d
+D modified
 e
 f`;

    const expected = `a
b
c
D modified
e
f
g`;

    const result = applyUnifiedDiff(original, diff);
    expect(result).toBe(expected);
  });

  it('should throw error for invalid diff format', () => {
    const original = 'some content';
    const invalidDiff = 'this is not a valid diff';

    // Resilient parser returns original content for invalid diffs
    const result = applyUnifiedDiff(original, invalidDiff);
    expect(result).toBe(original);
  });

  it('should handle diffs with no changes', () => {
    const original = `unchanged content
stays the same`;

    const diff = `--- a/file.txt
+++ b/file.txt`;

    // Note: Implementation adds a trailing newline
    const result = applyUnifiedDiff(original, diff);
    expect(result).toBe(original + '\n');
  });

  it('should apply complex real-world diff', () => {
    const original = `export class MyClass {
  constructor() {
    this.value = 0;
  }

  increment() {
    this.value++;
  }

  getValue() {
    return this.value;
  }
}`;

    const diff = `--- a/myclass.js
+++ b/myclass.js
@@ -1,8 +1,12 @@
 export class MyClass {
-  constructor() {
-    this.value = 0;
+  constructor(initialValue = 0) {
+    this.value = initialValue;
+    this.history = [initialValue];
   }

   increment() {
     this.value++;
+    this.history.push(this.value);
   }

   getValue() {
@@ -10,3 +14,7 @@ export class MyClass {
     return this.value;
   }
+
+  getHistory() {
+    return [...this.history];
+  }
 }`;

    const expected = `export class MyClass {
  constructor(initialValue = 0) {
    this.value = initialValue;
    this.history = [initialValue];
  }

  increment() {
    this.value++;
    this.history.push(this.value);
  }

  getValue() {
    return this.value;
  }

  getHistory() {
    return [...this.history];
  }
}`;

    const result = applyUnifiedDiff(original, diff);
    expect(result).toBe(expected);
  });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { SCOFFormat } from './scof';
import { CodeGenerationStreamingState } from './base';

describe('SCOF Parser - Comprehensive Tests', () => {
    let parser: SCOFFormat;
    let mockCallbacks: {
        onFileOpen: ReturnType<typeof vi.fn>;
        onFileChunk: ReturnType<typeof vi.fn>;
        onFileClose: ReturnType<typeof vi.fn>;
    };

    beforeEach(() => {
        parser = new SCOFFormat();
        mockCallbacks = {
            onFileOpen: vi.fn(),
            onFileChunk: vi.fn(),
            onFileClose: vi.fn(),
        };
    });

    const createInitialState = (): CodeGenerationStreamingState => ({
        accumulator: '',
        completedFiles: new Map(),
        parsingState: parser['initializeSCOFState'](),
    });

    const processChunk = (chunk: string, state: CodeGenerationStreamingState) => {
        return parser.parseStreamingChunks(
            chunk,
            state,
            mockCallbacks.onFileOpen,
            mockCallbacks.onFileChunk,
            mockCallbacks.onFileClose
        );
    };

    describe('Basic Shell Command Parsing', () => {
        it('should parse basic cat > file << EOF format', () => {
            const chunk = `cat > test.js << 'EOF'
console.log('Hello World');
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(mockCallbacks.onFileOpen).toHaveBeenCalledWith('test.js');
            expect(mockCallbacks.onFileClose).toHaveBeenCalledWith('test.js');
            expect(result.completedFiles.has('test.js')).toBe(true);

            const file = result.completedFiles.get('test.js');
            expect(file?.fileContents).toBe("console.log('Hello World');");
        });

        it('should handle double-quoted EOF markers', () => {
            const chunk = `cat > test.py << "EOF"
def hello():
        print("Hello")
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('test.py')).toBe(true);
            const file = result.completedFiles.get('test.py');
            expect(file?.fileContents).toBe('def hello():\n        print("Hello")');
        });

        it('should handle unquoted EOF markers', () => {
            const chunk = `cat > config.json << EOF
{
    "name": "test",
    "version": "1.0.0"
}
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('config.json')).toBe(true);
        });
    });

    describe('LLM Error Resilience', () => {
        it('should handle extra spaces in commands', () => {
            const chunk = `cat     >     file.js     <<     'EOF'
const x = 1;
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('file.js')).toBe(true);
        });

        it('should handle missing spaces around operators', () => {
            const chunk = `cat>file.js<<'EOF'
const compact = true;
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('file.js')).toBe(true);
        });

        it('should handle file paths with spaces (quoted)', () => {
            const chunk = `cat > "my file.js" << 'EOF'
// File with spaces in name
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('my file.js')).toBe(true);
        });

        it('should handle mismatched quotes', () => {
            const chunk = `cat > "file.js' << 'EOF'
// Mismatched quotes
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            // Parser should handle this gracefully
            expect(result.completedFiles.size).toBeGreaterThanOrEqual(0);
        });

        it('should handle mixed case commands', () => {
            const chunk = `CAT > file.txt << 'EOF'
Mixed case command
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('file.txt')).toBe(true);
        });
    });

    describe('Content Edge Cases', () => {
        it('should handle EOF marker in content', () => {
            const chunk = `cat > script.sh << 'MARKER'
#!/bin/bash
echo "This is not EOF"
if [ "$1" = "EOF" ]; then
    echo "Parameter is EOF"
fi
MARKER
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('script.sh')).toBe(true);
            const file = result.completedFiles.get('script.sh');
            expect(file?.fileContents).toContain('Parameter is EOF');
        });

        it('should handle special characters in content', () => {
            const chunk = `cat > special.txt << 'EOF'
Special chars: !@#$%^&*()_+-=[]{}|;':",./<>?
Escapes: \n \t \\ \" \'
Unicode: 你好 🌍 émojis
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            const file = result.completedFiles.get('special.txt');
            expect(file?.fileContents).toContain('!@#$%^&*()');
            expect(file?.fileContents).toContain('你好 🌍 émojis');
        });

        it('should handle empty files', () => {
            const chunk = `cat > empty.txt << 'EOF'
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('empty.txt')).toBe(true);
            const file = result.completedFiles.get('empty.txt');
            expect(file?.fileContents).toBe('');
        });

        it('should handle very long lines', () => {
            const longLine = 'a'.repeat(1000);
            const chunk = `cat > long.txt << 'EOF'
${longLine}
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            const file = result.completedFiles.get('long.txt');
            expect(file?.fileContents).toBe(longLine);
        });
    });

    describe('Streaming and Chunking', () => {
        it('should handle command split across chunks', () => {
            const chunk1 = 'cat > test.js';
            const chunk2 = " << 'EOF'\nconsole.log('test');\nEOF\n";

            let state = createInitialState();
            state = processChunk(chunk1, state);
            expect(mockCallbacks.onFileOpen).not.toHaveBeenCalled();

            state = processChunk(chunk2, state);
            expect(mockCallbacks.onFileOpen).toHaveBeenCalledWith('test.js');
            expect(state.completedFiles.has('test.js')).toBe(true);
        });

        it('should handle content split across chunks', () => {
            const chunk1 = "cat > multi.js << 'EOF'\nfunction test() {\n    const x = ";
            const chunk2 = "42;\n    return x;\n}\nEOF\n";

            let state = createInitialState();
            state = processChunk(chunk1, state);
            state = processChunk(chunk2, state);

            const file = state.completedFiles.get('multi.js');
            expect(file?.fileContents).toContain('const x = 42;');
        });

        it('should handle EOF marker split across chunks', () => {
            const chunk1 = "cat > split.txt << 'EOF'\nContent here\nEO";
            const chunk2 = "F\n";

            let state = createInitialState();
            state = processChunk(chunk1, state);
            state = processChunk(chunk2, state);

            expect(state.completedFiles.has('split.txt')).toBe(true);
        });

        it('should handle multiple files in sequence', () => {
            const chunk = `cat > file1.js << 'EOF'
console.log('File 1');
EOF

cat > file2.js << 'EOF'
console.log('File 2');
EOF

cat > file3.js << 'EOF'
console.log('File 3');
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.size).toBe(3);
            expect(mockCallbacks.onFileOpen).toHaveBeenCalledTimes(3);
            expect(mockCallbacks.onFileClose).toHaveBeenCalledTimes(3);
        });
    });

    describe('Patch/Diff Commands', () => {
        it('should handle patch commands', () => {
            const chunk = `cat << 'PATCH' | patch test.js
--- a/test.js
+++ b/test.js
@@ -1,3 +1,3 @@
 function test() {
-    return false;
+    return true;
 }
PATCH
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(mockCallbacks.onFileOpen).toHaveBeenCalledWith('test.js');
            expect(result.completedFiles.has('test.js')).toBe(true);

            const file = result.completedFiles.get('test.js');
            expect(file?.format).toBe('unified_diff');
        });

        it('should extract filename from patch content', () => {
            const chunk = `# Updating existing file
cat << 'EOF' | patch src/utils/helper.js
--- a/src/utils/helper.js
+++ b/src/utils/helper.js
@@ -10,3 +10,5 @@
 export function helper() {
     return 'help';
 }
+
+export const VERSION = '1.0.0';
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('src/utils/helper.js')).toBe(true);
        });
    });

    describe('Comments and Metadata', () => {
        it('should handle comments before commands', () => {
            const chunk = `# This is a comment explaining the file
# It has multiple lines
cat > documented.js << 'EOF'
// File content
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('documented.js')).toBe(true);
        });

        it('should handle commands with trailing comments', () => {
            const chunk = `cat > test.js << 'EOF' # This creates a test file
console.log('test');
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('test.js')).toBe(true);
        });
    });

    describe('Error Cases', () => {
        it('should handle malformed commands gracefully', () => {
            const chunk = `this is not a valid command
cat > << 'EOF'
missing filename
EOF
`;

            const state = createInitialState();
            // Should not throw
            expect(() => processChunk(chunk, state)).not.toThrow();
        });

        it('should handle unclosed EOF blocks', () => {
            const chunk = `cat > unclosed.js << 'EOF'
This file is never closed
No EOF marker here`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            // File should remain in pending state
            expect(result.completedFiles.has('unclosed.js')).toBe(false);
            expect(mockCallbacks.onFileOpen).toHaveBeenCalledWith('unclosed.js');
            expect(mockCallbacks.onFileClose).not.toHaveBeenCalled();
        });

        it('should recover from errors and continue parsing', () => {
            const chunk = `cat > good1.js << 'EOF'
console.log('good 1');
EOF

cat > << 'EOF'
bad command - no filename
EOF

cat > good2.js << 'EOF'
console.log('good 2');
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            // Should have parsed the good files
            expect(result.completedFiles.has('good1.js')).toBe(true);
            expect(result.completedFiles.has('good2.js')).toBe(true);
        });
    });

    describe('Real-world Scenarios', () => {
        it('should handle React component file creation', () => {
            const chunk = `# Creating a React component
cat > Button.jsx << 'EOF'
import React from 'react';

export const Button = ({ onClick, children }) => {
    return (
        <button onClick={onClick}>
            {children}
        </button>
    );
};
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            const file = result.completedFiles.get('Button.jsx');
            expect(file?.fileContents).toContain('export const Button');
            expect(file?.fileContents).toContain('<button onClick={onClick}>');
        });

        it('should handle package.json creation with proper JSON', () => {
            const chunk = `cat > package.json << 'EOF'
{
    "name": "my-app",
    "version": "1.0.0",
    "scripts": {
        "start": "node index.js",
        "test": "jest"
    },
    "dependencies": {
        "express": "^4.18.0"
    }
}
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            const file = result.completedFiles.get('package.json');
            // Should be valid JSON
            expect(() => JSON.parse(file?.fileContents || '')).not.toThrow();
        });

        it('should handle creating nested directory files', () => {
            const chunk = `cat > src/components/Header.tsx << 'EOF'
import React from 'react';

interface HeaderProps {
    title: string;
}

export const Header: React.FC<HeaderProps> = ({ title }) => {
    return <h1>{title}</h1>;
};
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            expect(result.completedFiles.has('src/components/Header.tsx')).toBe(true);
        });
    });

    describe('Performance and Stress Tests', () => {
        it('should handle many small chunks efficiently', () => {
            const content = "cat > test.js << 'EOF'\nconst x = 1;\nEOF\n";
            let state = createInitialState();

            // Process one character at a time
            for (const char of content) {
                state = processChunk(char, state);
            }

            expect(state.completedFiles.has('test.js')).toBe(true);
        });

        it('should handle large files', () => {
            const largeContent = 'x'.repeat(10000);
            const chunk = `cat > large.txt << 'EOF'
${largeContent}
EOF
`;

            const state = createInitialState();
            const result = processChunk(chunk, state);

            const file = result.completedFiles.get('large.txt');
            expect(file?.fileContents.trim()).toBe(largeContent);
        });
    });
});

import { applyDiff, createSearchReplaceDiff, validateDiff, MatchingStrategy } from './search-replace';

describe('Search/Replace Diff Format', () => {
	describe('Basic Operations', () => {
		test('should apply simple search/replace', () => {
			const original = `function hello() {
	console.log("Hello World");
}`;

			const diff = `<<<<<<< SEARCH
	console.log("Hello World");
=======
	console.log("Hello Universe");
>>>>>>> REPLACE`;

			const result = applyDiff(original, diff);
			expect(result.content).toContain('console.log("Hello Universe");');
			expect(result.content).not.toContain('console.log("Hello World");');
			expect(result.results.blocksApplied).toBe(1);
			expect(result.results.blocksFailed).toBe(0);
		});

		test('should handle multiple lines in search/replace', () => {
			const original = `function calculate() {
	let a = 1;
	let b = 2;
	return a + b;
}`;

			const diff = `<<<<<<< SEARCH
	let a = 1;
	let b = 2;
	return a + b;
=======
	const sum = 3;
	return sum;
>>>>>>> REPLACE`;

			const result = applyDiff(original, diff);
			expect(result.content).toContain('const sum = 3;');
			expect(result.content).toContain('return sum;');
			expect(result.content).not.toContain('let a = 1;');
		});

		test('should handle empty search (pure addition)', () => {
			const original = `function test() {
	return 42;
}`;

			const diff = `<<<<<<< SEARCH

=======
// This is a new comment
>>>>>>> REPLACE`;

			const result = applyDiff(original, diff);
			expect(result.content).toContain('// This is a new comment');
			expect(result.content).toContain('function test()');
		});

		test('should handle empty replace (deletion)', () => {
			const original = `function test() {
	console.log("debug");
	return 42;
}`;

			const diff = `<<<<<<< SEARCH
	console.log("debug");
=======
>>>>>>> REPLACE`;

			const result = applyDiff(original, diff);
			expect(result.content).not.toContain('console.log("debug");');
			expect(result.content).toContain('return 42;');
		});

		test('should preserve indentation and formatting', () => {
			const original = `\tif (condition) {
\t\tconsole.log("test");
\t}`;

			const diff = `<<<<<<< SEARCH
\t\tconsole.log("test");
=======
\t\tconsole.log("updated");
\t\tconsole.log("added line");
>>>>>>> REPLACE`;

			const result = applyDiff(original, diff);
			expect(result.content).toBe(`\tif (condition) {
\t\tconsole.log("updated");
\t\tconsole.log("added line");
\t}`);
		});
	});

	describe('Error Handling', () => {
		test('should fail when search pattern is ambiguous', () => {
			const original = `const x = 1;
const x = 1;
const y = 2;`;

			const diff = `<<<<<<< SEARCH
const x = 1;
=======
const x = 10;
>>>>>>> REPLACE`;

			expect(() => applyDiff(original, diff, { strict: true }))
				.toThrow('found 2 times (ambiguous)');
		});

		test('should handle malformed blocks gracefully', () => {
			const original = 'const x = 1;';
			const diff = `<<<<<<< SEARCH
const x = 1;
=======
const x = 2;`; // Missing end marker

			expect(() => applyDiff(original, diff, { strict: true }))
				.toThrow("REPLACE block ended prematurely");
		});

		test('should handle missing separator', () => {
			const original = 'const x = 1;';
			const diff = `<<<<<<< SEARCH
const x = 1;
const x = 2;
>>>>>>> REPLACE`;

			expect(() => applyDiff(original, diff, { strict: true }))
				.toThrow("SEARCH block without corresponding REPLACE");
		});

		test('should apply successful blocks in non-strict mode', () => {
			const original = `line1
line2
line3`;

			const diff = `<<<<<<< SEARCH
line1
=======
line1_updated
>>>>>>> REPLACE

<<<<<<< SEARCH
lineX
=======
lineX_updated
>>>>>>> REPLACE

<<<<<<< SEARCH
line3
=======
line3_updated
>>>>>>> REPLACE`;

			const result = applyDiff(original, diff, { strict: false });
			expect(result.content).toContain('line1_updated');
			expect(result.content).toContain('line2'); // Unchanged
			expect(result.content).toContain('line3_updated');
			expect(result.content).not.toContain('lineX'); // Failed block ignored
		});

		test('should handle sequential dependency failures silently in non-strict mode', () => {
			// This test recreates a scenario where the second diff fails due to whitespace differences
			// after the first diff changes the content structure
			const original = `interface TileProps {
  value: number;
}
const TileComponent: React.FC<TileProps> = ({ value }) => {
  return (
    <motion.div>{value}</motion.div>
  );
};`;

			// First diff succeeds, second diff fails due to exact whitespace mismatch
			const diff = `<<<<<<< SEARCH
interface TileProps {
  value: number;
}
=======
interface TileProps {
  value: number;
  position?: { x: number; y: number };
}
>>>>>>> REPLACE

<<<<<<< SEARCH
const TileComponent: React.FC<TileProps> = ({ value }) => {
  return (
    <motion.div>{value}</motion.div>
  );
};
=======
const TileComponent: React.FC<TileProps> = ({ value, position }) => {
  return (
    <motion.div layoutId={position ? \`tile-\${position.x}-\${position.y}\` : undefined}>
      {value}
    </motion.div>
  );
};
>>>>>>> REPLACE`;

			const result = applyDiff(original, diff, { strict: false });

			// First diff should succeed
			expect(result.content).toContain('position?: { x: number; y: number };');

			// Second diff should apply successfully in this case
			// (This demonstrates proper sequential application)
			expect(result.content).toContain('({ value, position }) =>');
			expect(result.content).toContain('layoutId');
		});

		test('should provide detailed errors when all blocks fail', () => {
			const original = `const x = 1;
const y = 2;`;

			const diff = `<<<<<<< SEARCH
const a = 1;
=======
const a = 10;
>>>>>>> REPLACE

<<<<<<< SEARCH
const b = 2;
=======
const b = 20;
>>>>>>> REPLACE`;

			const result = applyDiff(original, diff, { strict: false });
			expect(result.results.blocksFailed).toBe(2);
			expect(result.results.errors.some(error => error.includes('All search/replace blocks failed'))).toBe(true);
		});

		test('should handle whitespace sensitivity in search patterns', () => {
			const original = `function test() {
    console.log("hello");
}`;

			// This diff has slightly different whitespace in search pattern
			const diff = `<<<<<<< SEARCH
function test() {
  console.log("hello");
}
=======
function test() {
    console.log("goodbye");
}
>>>>>>> REPLACE`;

			// Should fail due to whitespace mismatch, original preserved
			const result = applyDiff(original, diff, { 
				strict: false,
				matchingStrategies: [MatchingStrategy.EXACT]
			});
			expect(result.results.blocksFailed).toBe(1);
			expect(result.results.errors.some(error => error.includes('Search block not found'))).toBe(true);
		});

		test('should fail fast in strict mode when search pattern not found', () => {
			const original = `const x = 1;
const y = 2;
const z = 3;`;

			const diff = `<<<<<<< SEARCH
const x = 1;
=======
const x = 10;
>>>>>>> REPLACE

<<<<<<< SEARCH
const missing = 999;
=======
const missing = 1000;
>>>>>>> REPLACE

<<<<<<< SEARCH
const z = 3;
=======
const z = 30;
